	  var browsers = {
	    chrome: 'chrome',
	    chrome_android: 'and_chr',
	    edge: 'edge',
	    firefox: 'firefox',
	    firefox_android: 'and_ff',
	    safari: 'safari',
	    safari_ios: 'ios_saf',
	    webview_android: 'android',
	    samsunginternet_android: 'samsung',
	    opera_android: 'op_mob',
	    opera: 'opera',
	    qq_android: 'and_qq',
	    uc_android: 'and_uc',
	    kai_os: 'kaios'
	  };

